create table billing_templates (amount numeric(12,2), due_day_of_month integer not null, grace_period_days integer, is_active boolean, late_fee_penalty numeric(10,2), unit_rate numeric(10,2), apartment_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, distribution_method varchar(255) default 'FLAT_RATE' not null check ((distribution_method in ('FLAT_RATE','PER_SQFT','BY_BHK_TYPE','USAGE_BASED','PRO_RATA'))), frequency varchar(255) not null check ((frequency in ('MONTHLY','QUARTERLY','ANNUALLY','SPECIAL_ASSESSMENT'))), title varchar(255) not null, primary key (id));
alter table if exists billing_templates add constraint FKc5mqci3asotrwiwd36ifxgf6q foreign key (apartment_id) references apartments;
